/*
 * A087157  Satisfies a(1)=1, a(A087158(n+1)) = a(n)+1, with a(m)=1 for all m
 *          not found in A087158, where A087158(n+2)=A087158(n+1)+a(n)+1.
 * https://oeis.org/A087157
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   non‑recursive Sequenced by definition: a(1) = 1 If mi =
 *            A087158(i+1) (the “action” indices) then a(mi) = a(i) + 1 All
 *            other indices have value 1. The sequence is generated by walking
 *            the A087158 indices; for each step i (starting at 1) we set
 *            a(current_b) from a(i) and advance current_b by a(i)+1...
 * Range:     u8 n <= 105, u16 n <= 105, u32 n <= 105, u64 n <= 105,
 *            u128 n <= 105, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

/* Ensure the array can index up to min_cap (1‑based). New elements
   are initialised to 1.  The array may grow geometrically. */
static void ensure_cap(idx_t *cap, seq_t **arr, idx_t min_cap) {
    if (*cap >= min_cap)
        return;
    idx_t new_cap = (*cap) ? (*cap) * 2 : 1;
    while (new_cap < min_cap)
        new_cap <<= 1;            /* double until sufficient */
    seq_t *tmp = (seq_t *)realloc(*arr, (new_cap + 1) * sizeof(seq_t));
    if (!tmp)
        abort();                  /* out of memory */
    /* initialise the newly added elements to 1 */
    for (idx_t i = *cap + 1; i <= new_cap; ++i)
        tmp[i] = 1;
    *arr = tmp;
    *cap = new_cap;
}

seq_t a(idx_t n) {
    /* static state */
    static seq_t *vals = NULL;     /* 1‑based array of values */
    static idx_t capacity = 0;     /* allocated size (1‑based) */
    static idx_t last_step = 0;    /* number of steps processed */
    static idx_t current_b = 2;    /* next target index (A087158(i+1)) */

    /* one‑time allocation */
    if (!vals) {
        vals = (seq_t *)calloc(2, sizeof(seq_t));  /* indices 0..1 */
        if (!vals)
            abort();
        vals[1] = 1;                /* a(1) = 1 */
        capacity = 1;
        last_step = 0;
        current_b = 2;
    }

    /* expand storage so that index n is valid */
    ensure_cap(&capacity, &vals, n);

    /* generate steps until we've set a[n] (or it remains 1) */
    while (current_b <= n) {
        /* next step index */
        idx_t step = ++last_step;                /* 1‑based */

        /* ensure space for step and target indices */
        idx_t need = step > current_b ? step : current_b;
        ensure_cap(&capacity, &vals, need);

        /* set the target value */
        vals[current_b] = vals[step] + (seq_t)1;

        /* compute next target index, safely converting to idx_t */
        seq_t new_b = (seq_t)current_b + vals[step] + (seq_t)1;
        current_b = (idx_t)new_b;
    }

    return vals[n];
}
